import React, { useState } from 'react';
import { Mail, Lock } from 'lucide-react';

const LoginPage = ({ onLogin, onNavigate }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!email || !password) {
      setError('يرجى ملء جميع الحقول');
      return;
    }

    setLoading(true);
    const result = await onLogin(email, password);
    setLoading(false);

    if (!result.success) {
      setError(result.error || 'البريد الإلكتروني أو كلمة المرور غير صحيحة');
    }
  };

  return (
    <div className="min-h-screen bg-[#e3e4e9]" dir="rtl">
      <Header onNavigate={onNavigate} />

      <main className="flex items-center justify-center py-20 px-4">
        <div className="bg-white rounded-2xl shadow-xl p-8 w-full max-w-md">
          <h2 className="text-3xl font-bold text-[#0c1f40] text-center mb-2">
            تسجيل الدخول
          </h2>
          <p className="text-gray-600 text-center mb-8">
            مرحبًا بعودتك إلى نظام مَكمَن
          </p>

          {error && (
            <div className="bg-red-100 text-red-700 p-3 rounded-lg mb-4 text-sm">
              {error}
            </div>
          )}

          <form onSubmit={handleSubmit} className="space-y-5">
            <div>
              <label className="text-sm font-medium text-gray-700">البريد الإلكتروني</label>
              <div className="relative mt-1">
                <Mail className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input
                  type="email"
                  className="w-full pr-10 py-3 border rounded-lg focus:ring-2 focus:ring-[#0c1f40]"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>
            </div>

            <div>
              <label className="text-sm font-medium text-gray-700">كلمة المرور</label>
              <div className="relative mt-1">
                <Lock className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 w-5 h-5" />
                <input
                  type="password"
                  className="w-full pr-10 py-3 border rounded-lg focus:ring-2 focus:ring-[#0c1f40]"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </div>
            </div>

            <button
              disabled={loading}
              className="w-full bg-[#0c1f40] text-white py-3 rounded-lg font-bold hover:bg-[#15325f]"
            >
              {loading ? 'جاري الدخول...' : 'تسجيل الدخول'}
            </button>
          </form>

          <p className="text-center text-sm mt-6 text-gray-600">
            ليس لديك حساب؟{' '}
            <button
              onClick={() => onNavigate('signin')}
              className="text-[#0c1f40] font-semibold hover:underline"
            >
              إنشاء حساب
            </button>
          </p>
        </div>
      </main>

      <Footer />
    </div>
  );
};

export default LoginPage;
